contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        uint256 baseTokenAmount
    ) public payable {
        // Setup: initialize the pool as the test contract acting through c
        c.initialize(
            address(0),
            address(this),
            uint128(100e18),
            uint128(100e18),
            uint56(0),
            uint16(0),
            bytes32(0),
            false,
            false
        );

        uint256 beforeVBase = uint256(c.virtualBaseTokenReserves());
        uint256 beforeVNft = uint256(c.virtualNftReserves());

        uint256 weightSum = 0;
        for (uint256 i = 0; i < tokenIds.length; i++) {
            weightSum += tokenWeights[i];
        }

        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        bool reverted;
        try c.buy{value: baseTokenAmount}(
            tokenIds,
            tokenWeights,
            C.MerkleMultiProof({proof: new bytes32[](0), flags: new bool[](0)})
        ) returns (uint256 n, uint256 f, uint256 p) {
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(
                uint256(c.virtualBaseTokenReserves()) == beforeVBase + netInputAmount - feeAmount - protocolFeeAmount &&
                uint256(c.virtualNftReserves()) == beforeVNft - weightSum
            );
        } else {
            assert(true);
        }
    }
}

